import{_ as i,o as t,c as a,a3 as r}from"./chunks/framework.z_KJ15Ep.js";const u=JSON.parse('{"title":"Setzefilter","description":"","frontmatter":{"title":"Setzefilter","source_pageid":117,"source_revision":557},"headers":[],"relativePath":"reporting/rap/setzefilter.md","filePath":"reporting/rap/setzefilter.md"}'),s={name:"reporting/rap/setzefilter.md"};function n(l,e,d,p,h,o){return t(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="setzefilter" tabindex="-1">Setzefilter <a class="header-anchor" href="#setzefilter" aria-label="Permalink to &quot;Setzefilter&quot;">​</a></h1><h2 id="beschreibung" tabindex="-1">Beschreibung <a class="header-anchor" href="#beschreibung" aria-label="Permalink to &quot;Beschreibung&quot;">​</a></h2><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">procedure</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;"> SetzeFilter</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(Pipeline: TppDbPipeline; </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">const</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> Filter: </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">String</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>Schränkt die Datensätze durch die übergebene Filterbedingung ein.</p><h2 id="parameter" tabindex="-1">Parameter <a class="header-anchor" href="#parameter" aria-label="Permalink to &quot;Parameter&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Parameter</th><th>Bedeutung</th></tr></thead><tbody><tr><td><code>Pipeline</code></td><td>Datenquelle, die gefiltert werden soll</td></tr><tr><td><code>Filter</code></td><td>der neue Filter. Ist der Filterstring leer, wird die Filterung entfernt.</td></tr></tbody></table><h2 id="beispiel" tabindex="-1">Beispiel <a class="header-anchor" href="#beispiel" aria-label="Permalink to &quot;Beispiel&quot;">​</a></h2><p>Definieren Sie die Filterbedingungen im Report wie folgt:</p><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">Setzefilter(Klassenlehrer_mit_Faechern,</span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;Fachkrz=M;D&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> );</span></span></code></pre></div><p>d.h. wenn mehrere Optionen in Frage kommen (OR-Bedingung), brauchen die nur durch Semikolon getrennt angegeben zu werden.</p><div class="language-pascal vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">pascal</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">SetzeFilter(Klassen, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&#39;KlassenlehrerKrz &lt;&gt;&quot;&quot;&#39;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">);</span></span></code></pre></div><p>d.h. bei Abfragen &quot;ungleich Leerstring&quot; können die &quot;doppelten Hochkommas&quot; (über der 2 auf der Tastatur) verwendet werden.</p><p>Filterbedingungen der Art <code>Klasse=05*</code> oder <code>Klasse=*A</code> bewirken eine Filterung mit allen für den * vorkommenden Zeichen. (Wildcard)</p><p>Im übrigen können auch mehrere Aufrufe von SetzeFilter (z.B. für verschiedene Datenquellen) genutzt werden.</p><p>Noch ein Hinweis: Manchmal funktioniert die Filterung in der Vorschau des Designers nicht, im &quot;Druckbetrieb&quot; wird dann aber korrekt gefiltert.</p><p><strong>Zurück zu <a href="/reporting/rap.html">RAP-Funktionen</a></strong></p><hr><p><a href="https://schulverwaltungsinfos.nrw.de/svws/wiki/index.php?title=Setzefilter" target="_blank" rel="noreferrer">Originalartikel im Wiki</a> · Quellrevision 557.</p>',18)])])}const g=i(s,[["render",n]]);export{u as __pageData,g as default};
